{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user",
      "severity": "MEDIUM",
      "explanation": "IAM users with console access can pose a security risk if their credentials are compromised. This user does not explicitly disable console access, which is a best practice."
    }
  ],
  "patched_code": "resource "aws_iam_user" "privesc15-PassExistingRoleToNewLambdaThenInvoke-user" {
  name = "privesc15-PassExistingRoleToNewLambdaThenInvoke-user"
  path = "/"
  tags = {
    "forbid_console_access" = "true"
  }
}

resource "aws_iam_user_policy" "deny_console_access" {
  name   = "deny-console-access"
  user   = aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name
  policy = <<EOT
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Deny",
      "Action": "aws-portal:*",
      "Resource": "*"
    }
  ]
}
EOT
}
",
  "fix_summary": "Added a policy to explicitly deny console access for the IAM user to comply with best practices and mitigate potential risks."
}
